/// <summary>
/// Service to synchronize and log changes in query store query hints.
/// </summary>
public class DBMSQLQueryStoreQueryHintSyncService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// Synchronizes current query hints view with previous snapshot, logs changes, and updates snapshot.
/// </summary>
public void process()
{
    DBMSQLQueryStoreQueryHintAgg aggView;
    DBMSQLQueryStoreQuery queryView;
    DBMSQLQueryStoreQueryHintSnapshot snapshotTable;
    DBMSQLQueryStoreQueryHintLog logTable;

    ttsbegin;

    // 1. Detect and log INSERT changes (new query hints aggregated per QueryId)
    insert_recordset logTable (QueryId, NewQueryHintText, QueryHash)
        select QueryId, QueryHintText from aggView
            join QueryHash from queryView
            where queryView.QueryId == aggView.QueryId
            notexists join snapshotTable
            where snapshotTable.QueryId == aggView.QueryId;

    // 2. Detect and log UPDATE changes (hints aggregated per QueryId changed)
    insert_recordset logTable (QueryId, QueryHash, OldQueryHintText, NewQueryHintText)
        select QueryId, QueryHash, QueryHintText from snapshotTable
            join QueryHintText from aggView
            where aggView.QueryId == snapshotTable.QueryId
               && aggView.QueryHintHash != snapshotTable.QueryHintHash;

    update_recordset logTable
        setting ChangeType = DatabaseLogType::Update
        where logTable.ChangeType == DatabaseLogType::Insert
           && logTable.OldQueryHintText != ''
           && logTable.NewQueryHintText != '';

    // 3. Detect and log DELETE changes (hints aggregated per QueryId no longer exist in view)
    insert_recordset logTable (QueryId, QueryHash, OldQueryHintText)
        select QueryId, QueryHash, QueryHintText from snapshotTable
            notexists join aggView
            where aggView.QueryId == snapshotTable.QueryId;

    update_recordset logTable
        setting ChangeType = DatabaseLogType::Delete
        where logTable.ChangeType == DatabaseLogType::Insert
           && logTable.OldQueryHintText != ''
           && logTable.NewQueryHintText == '';

    // 4. Update snapshot table with current hints and hash
    delete_from snapshotTable;

    insert_recordset snapshotTable (QueryId, QueryHintText, QueryHintHash, QueryHash)
        select QueryId, QueryHintText, QueryHintHash from aggView
            join QueryHash from queryView
            where queryView.QueryId == aggView.QueryId;

    // 5. Clean up log records for query IDs that no longer exist in the main query store table
    delete_from logTable
        notexists join queryView
        where queryView.QueryId == logTable.QueryId;

    ttscommit;
}
